catalog_script_client.script:
function onSubmit() {

    var gaDoesContactExist = new GlideAjax('global.HSBCContactManagementUtils');
    gaDoesContactExist.addParam('sysparm_name', 'doesCombinationExist');
    gaDoesContactExist.addParam('sysparm_counterparty_code', g_form.getValue("counterparty_code"));
    gaDoesContactExist.addParam('sysparm_business_process', g_form.getValue("business_process"));
    gaDoesContactExist.addParam('sysparm_email_type', g_form.getValue("email_type"));
    gaDoesContactExist.addParam('sysparm_email_address', g_form.getValue("email_address"));
    gaDoesContactExist.getXMLWait();

    var answer = gaDoesContactExist.getAnswer();

    if (answer) {
        var returnedData = JSON.parse(answer);
        g_form.addErrorMessage(returnedData.message);
        return false;

    }
}
